// Writes src/comment-json/esprima.js: esprima 4.0.1's tokenizer, the modules
// of its build that `esprima.tokenize` needs (character, assert, error
// handler, messages, scanner, token names, tokenizer), unchanged, under a
// small loader in place of webpack's, and its `tokenize`. comment-json uses
// nothing else of esprima.
// Usage: node scripts/esprima.ts
import { readFileSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import { dirname, join } from "node:path";

const require = createRequire(import.meta.url);
const root = dirname(
  require.resolve("esprima/package.json", { paths: [dirname(require.resolve("comment-json"))] }),
);
const source = readFileSync(join(root, "dist/esprima.js"), "utf8");
const license = readFileSync(join(root, "LICENSE.BSD"), "utf8");

// The build's modules, by id: "/* <id> */\n/***/ function(module, exports, ...) {" to the next.
const starts = [
  ...source.matchAll(
    /^\/\* (\d+) \*\/\n\/\*\*\*\/ (function\(module, exports(?:, __webpack_require__)?\) \{)$/gm,
  ),
];
const modules = new Map<number, string>();
for (const [k, match] of starts.entries()) {
  const end = starts[k + 1]?.index ?? source.indexOf("/******/ ])", match.index);
  const body = source
    .slice(match.index! + match[0].length, end)
    .replace(/\n\/\*\*\*\/ \},?\s*$/, "");
  modules.set(Number(match[1]), `function (module, exports, __webpack_require__) {${body}\n}`);
}
const NEEDED = [4, 9, 10, 11, 12, 13, 15];
const tokenize = source.match(
  /\tfunction tokenize\(code, options, delegate\) \{[\s\S]*?\n\t\}\n/,
)![0];

writeFileSync(
  "src/comment-json/esprima.js",
  `// Generated by scripts/esprima.ts from esprima 4.0.1: its tokenizer, the
// modules of its build that \`tokenize\` needs, unchanged.
/*
${license.trim()}
*/
/* eslint-disable */
var modules = {
${NEEDED.map((id) => `  ${id}: ${modules.get(id)}`).join(",\n")}
};
var cache = {};
function __webpack_require__(id) {
  if (cache[id]) return cache[id].exports;
  var module = (cache[id] = { exports: {} });
  modules[id].call(module.exports, module, module.exports, __webpack_require__);
  return module.exports;
}
var tokenizer_1 = __webpack_require__(15);
export ${tokenize.trim()}
`,
);
console.log("src/comment-json/esprima.js");
